import more_itertools as mi

# Exhaustive property test: peek() == next() would return, and peek doesn't advance
# For various maxlens and operations
from itertools import count

def check(maxlen, ops):
    s = mi.seekable(map(str, range(20)), maxlen=maxlen)
    # ops: list of 'peek','next','seek:X','bool'
    for op in ops:
        if op == 'peek':
            # peek should equal next would return, without advancing
            # To test without advancing, peek twice should be same, and next after should be same
            try:
                p1 = s.peek()
            except StopIteration:
                # next should also raise
                try:
                    n = next(s)
                    print(f"FAIL maxlen={maxlen} ops={ops}: peek raised but next returned {n}")
                    return False
                except StopIteration:
                    continue
            try:
                p2 = s.peek()
            except StopIteration:
                print(f"FAIL maxlen={maxlen} ops={ops}: first peek {p1} but second raised")
                return False
            if p1 != p2:
                print(f"FAIL maxlen={maxlen} ops={ops}: peek1 {p1} != peek2 {p2}")
                return False
            try:
                n = next(s)
            except StopIteration:
                print(f"FAIL maxlen={maxlen} ops={ops}: peek {p1} but next raised")
                return False
            if p1 != n:
                print(f"FAIL maxlen={maxlen} ops={ops}: peek {p1} != next {n}")
                return False
        elif op == 'next':
            try:
                next(s)
            except StopIteration:
                pass
        elif op.startswith('seek:'):
            s.seek(int(op.split(':')[1]))
        elif op == 'bool':
            b = bool(s)
            # bool should be True iff peek succeeds
            try:
                s.peek()
                expected = True
            except StopIteration:
                expected = False
            if b != expected:
                print(f"FAIL maxlen={maxlen} ops={ops}: bool {b} != expected {expected}")
                return False
    return True

# Try various sequences
import random
random.seed(0)
for maxlen in [0,1,2,None]:
    for trial in range(50):
        ops = []
        for _ in range(10):
            r = random.random()
            if r < 0.4:
                ops.append('peek')
            elif r < 0.7:
                ops.append('next')
            elif r < 0.85:
                ops.append(f'seek:{random.randint(0,5)}')
            else:
                ops.append('bool')
        ok = check(maxlen, ops)
        if not ok:
            print(f"  failed ops: {ops}")
            break
    else:
        print(f"maxlen={maxlen} all 50 trials passed")
